    id: "b-06", chapter: 10,
    scenario: `
<p>M社は、従業員 200 名の経営コンサルティング会社である。M社では、従業員は週 3 日までテレワークを行うことができる。テレワークでは、会社が貸与したノート PC（以下、貸与PC という）を使用し、貸与PC には覗き見防止フィルタが同梱されている。社内のファイルサーバやメールサーバには、会社が指定した VPN を経由して接続する。M社のテレワーク規程の主な内容を表1に示す。</p>
<p>表1 テレワーク規程（抜粋）</p>
<table>
<tr><th>項番</th><th>内容</th></tr>
<tr><td>1</td><td>業務には貸与PC だけを使用する。</td></tr>
<tr><td>2</td><td>社内システムへの接続は、会社が指定した VPN を経由する。</td></tr>
<tr><td>3</td><td>公共の場所（カフェ、駅、交通機関の車内など）で業務を行う場合は、覗き見防止フィルタを使用し、会話で業務情報を話さない。</td></tr>
<tr><td>4</td><td>業務データを、私物の記憶媒体や個人で契約したクラウドサービスに保存しない。</td></tr>
<tr><td>5</td><td>貸与PC に不具合が生じた場合は、情報システム部のヘルプデスクに連絡する。</td></tr>
</table>
<p>ある週に、M社のコンサルティング部の従業員が次の a〜f の行動をとった。</p>
<ul>
<li>a：自宅で貸与PC を使い、VPN 経由で社内のファイルサーバにアクセスして、提案書を作成した。</li>
<li>b：貸与PC の起動が遅かったので、ヘルプデスクに連絡した上で、修理が終わるまで私物のノート PC から VPN に接続して作業した。</li>
<li>c：顧客訪問の合間にカフェで、覗き見防止フィルタを付けた貸与PC から VPN 経由でメールを確認した。</li>
<li>d：提案書を自宅のプリンタで印刷するため、個人で契約しているオンラインストレージに提案書をアップロードし、私物のタブレットから印刷した後、直ちに削除した。</li>
<li>e：出張中の新幹線の車内で、同僚と電話で顧客との契約金額について打合せをした。</li>
<li>f：自宅で貸与PC を使い、VPN に接続せずに、業界団体の Web サイトで公開されている統計資料を閲覧した。</li>
</ul>
<p>なお、M社では、私物の機器の業務利用を認める制度（BYOD）は導入していない。また、情報システム部は、貸与PC の故障時に代替機を即日貸し出す運用を行っている。</p>`,
    question: "M社のテレワーク規程に違反している行動だけを全て挙げた組合せはどれか。",
    choices: ["b, d", "b, d, e", "b, d, f", "b, d, e, f", "c, d, e", "a, b, d, e"],
