<p>E社は、従業員 400 名のソフトウェア開発会社であり、本社ビルの 5 階と 6 階に執務室がある。執務室では顧客から預かったデータを使った開発作業を行っており、入退室の管理は総務部が担当している。IC カードは入社時に従業員ごとに発行し、退職時に回収している。執務室には平日の 7:00〜22:00 の間だけ入室でき、それ以外の時間帯に入室する場合は総務部への事前申請が必要である。E社の入退室管理の概要は表1のとおりである。</p>
