<p>E社は、従業員 300 名の事務用品の卸売業者であり、本社に営業部、物流部及び管理部がある。社内システムの運用は管理部の情報システム課（4 名）が担当しており、情報セキュリティリーダーは情報システム課の F主任である。</p>
