      "版 1 の利用者も攻撃を受けるおそれがあるので、版 1 の修正版も作成し、全ての版の修正版がそろうまで、版 2 と版 3 の修正版の提供を見合わせる。",
      "調査結果と修正版の提供予定時期を JPCERT/CC に回答し、修正版の提供開始に合わせて脆弱性情報を公表できるよう、公表日を調整する。",
