    question: "a〜e のうち、指摘1〜3 の全てを解決するために必要な対応だけを全て挙げた組合せはどれか。",
    choices: ["a, b", "a, c", "a, d", "a, e", "b, c", "b, d", "b, e", "c, d", "c, e", "d, e"],
    answer: 8,
    explanation: "c により通常の操作が個人 ID で記録されて実施者を特定でき（指摘1）、admin のパスワード変更と封印で T さんも使えなくなります（指摘2）。e により運用課の担当者はログを改ざんできなくなり、第三者が確認します（指摘3）。a は共用のスマートフォンを使うため実施者を特定できず、b は共用を続けるので指摘1 が残ります。d は保存期間を延ばすだけで、ログの削除や変更は防げません。",
